UPDATE T_TQ_SCHEDULE_RESULT as a JOIN (
SELECT #{item.id} AS id, #{item.batchNo} as batch_no, #{item.orderNo} as order_no FROM DUAL
) tempTable ON a.id = tempTable.id SET a.batch_no = tempTable.batch_no, a.order_no = tempTable.order_no where a.del_flag = '0'

mapper.select:
select ID, FACTORY_CODE, MACHINE_RANGE, MACHINE_COUNT, SHIFT_COUNT from T_TQ_STOCK_SHIFT_CONFIG where IS_DELETE = 0
and FACTORY_CODE = #{factoryCode}
order by MACHINE_COUNT
